import React, { useState, useEffect } from 'react';
import bg1 from '../../assets/cec11.jpeg';
import bg2 from '../../assets/cec12.jpg';
import bg3 from '../../assets/cec14.jpeg';

const slides = [
    {
        id: 1,
        image: bg1,
        title: "Top Ranking Institution",
        subtitle: "Consistently ranked among the top engineering colleges in the state."
    },
    {
        id: 2,
        image: bg2,
        title: "Distinguished Alumni",
        subtitle: "Our alumni hold key positions in global tech giants and leading research organizations."
    },
    {
        id: 3,
        image: bg3,
        title: "Innovation Hub",
        subtitle: "Fostering a culture of research, startups, and technological advancements."
    }
];

const Achievements = () => {
    const [currentIndex, setCurrentIndex] = useState(0);

    // Automatic sliding effect
    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentIndex((prevIndex) => (prevIndex + 1) % slides.length);
        }, 4000);
        return () => clearInterval(interval);
    }, []);

    return (
        <section id="achievements" className="py-10 bg-transparent border-t border-border/30">
            <div className="max-w-[95%] mx-auto px-4 lg:px-6">
                <div className="mb-10 text-center">
                    <h2 className="text-[2.25rem] font-display font-bold text-slate-800 mb-4 uppercase tracking-wide">Our Achievements</h2>
                    <div className="w-16 h-1 bg-coral mx-auto"></div>
                </div>

                <div className="relative w-full overflow-hidden rounded-xl shadow-lg border border-slate-200 bg-coral">
                    {/* Slider track */}
                    <div 
                        className="flex h-[450px] md:h-[650px] w-full transition-transform duration-1000 ease-in-out"
                        style={{ transform: `translateX(-${currentIndex * 100}%)` }}
                    >
                        {slides.map((slide, index) => (
                            <div
                                key={slide.id}
                                className="relative h-full min-w-full bg-cover bg-center"
                                style={{ backgroundImage: `url(${slide.image})` }}
                            >
                                {/* Overlay */}
                                <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-slate-800/50 to-transparent"></div>

                                {/* Text Content */}
                                <div className="absolute inset-0 flex flex-col items-center justify-end text-center p-8 md:p-12 mb-10">
                                    <div className={`transition-all duration-1000 transform ${currentIndex === index ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'}`}>
                                        <h3 className="text-4xl md:text-6xl font-display font-bold text-white mb-6 drop-shadow-md">
                                            {slide.title}
                                        </h3>
                                        <p className="text-xl md:text-2xl text-slate-200 max-w-4xl mx-auto drop-shadow-sm leading-relaxed">
                                            {slide.subtitle}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Indicator Dots */}
                    <div className="absolute bottom-6 left-1/2 flex -translate-x-1/2 gap-3 z-10">
                        {slides.map((_, index) => (
                            <button
                                key={index}
                                onClick={() => setCurrentIndex(index)}
                                aria-label={`Go to slide ${index + 1}`}
                                className={`transition-all duration-500 ease-in-out rounded-full ${
                                    currentIndex === index ? 'bg-coral w-8 h-2.5 shadow-[0_0_8px_rgba(240,113,103,0.8)]' : 'bg-white/60 hover:bg-white w-2.5 h-2.5'
                                }`}
                            ></button>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

export default Achievements;
